// Parse Kactus email body
const text = $input.first().json.text || $input.first().json.html || '';

// Extract contact name: "de la part de {Name} de la société"
const nameMatch = text.match(/de la part de ([\w\-éèêëàâùûôîïç]+)/i);
const name = nameMatch ? nameMatch[1] : '';

// Extract company: "de la société {COMPANY} pour"
const companyMatch = text.match(/de la soci[ée]t[ée] ([^\n]+?) pour/i);
const company = companyMatch ? companyMatch[1].trim() : '';

// Extract event type + guests: "{EventType} pour {N} personnes"
const eventMatch = text.match(/pour son [ée]v[ée]nement\s*[:\s]*\n?\s*(.+?)\s+pour\s+(\d+)\s+personnes/is);
let eventType = '';
let guestCount = 0;
if (eventMatch) {
  eventType = eventMatch[1].trim();
  guestCount = parseInt(eventMatch[2], 10);
}

// Extract date: "le {DD} {month} {YYYY}" or "le {DD}/{MM}/{YYYY}"
const months = { 'janvier':'01','février':'02','mars':'03','avril':'04','mai':'05','juin':'06','juillet':'07','août':'08','septembre':'09','octobre':'10','novembre':'11','décembre':'12' };
let date = '';
const dateMatch = text.match(/le (\d{1,2})\s+(janvier|f[ée]vrier|mars|avril|mai|juin|juillet|ao[ûu]t|septembre|octobre|novembre|d[ée]cembre)\s+(\d{4})/i);
if (dateMatch) {
  const day = dateMatch[1].padStart(2, '0');
  const month = months[dateMatch[2].toLowerCase()] || '01';
  date = `${day}/${month}/${dateMatch[3]}`;
}

// Extract budget: "Budget de {N} €" or "Budget de {N N} €"
const budgetMatch = text.match(/Budget de ([\d\s]+)\s*€/i);
const budget = budgetMatch ? budgetMatch[1].replace(/\s/g, '') : '';

const message = budget ? `Budget client : ${parseInt(budget).toLocaleString('fr-FR')} €` : '';

return [{ json: { source: 'Kactus', name, company, eventType, guestCount, date, message } }];
